-- Test-only columns and enum values from the inspected existing Supabase schema.
-- No production data, keys or runtime configuration.
CREATE TYPE public.recommendation_target_type AS ENUM('library_resource','event','shared_resource');
CREATE TYPE public.marketplace_listing_type AS ENUM('sale','loan','donation','exchange');
CREATE TYPE public.marketplace_transaction_status AS ENUM('requested','accepted','rejected','completed','cancelled');
CREATE TYPE public.document_type AS ENUM('course','td','tp','exam','handout','other');
CREATE TYPE public.chat_sender AS ENUM('user','assistant','system');
CREATE TYPE public.complaint_type AS ENUM('pedagogical','technical');
CREATE TYPE public.complaint_status AS ENUM('submitted','under_review','resolved','rejected');
CREATE TYPE public.knowledge_source_type AS ENUM('announcement','course_document','module','timetable','event','library_resource','faq');
CREATE TYPE public.item_condition AS ENUM('new','very_good','good','acceptable','not_applicable');
CREATE TYPE public.marketplace_listing_status AS ENUM('available','reserved','completed','withdrawn');
CREATE TYPE public.campus_location_type AS ENUM('classroom','amphitheatre','lab','department','library','service','other');
CREATE TYPE public.resource_type AS ENUM('book','article','project_report','course_support','website','other');
CREATE TYPE public.resource_visibility AS ENUM('all_students','selected_programs','private');
CREATE TYPE public.lost_found_type AS ENUM('lost','found');
CREATE TYPE public.lost_found_status AS ENUM('open','claimed','returned','closed');
CREATE TABLE public.complaint_messages(id uuid NOT NULL DEFAULT gen_random_uuid(),complaint_id uuid NOT NULL,author_id uuid NOT NULL,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.recommendations(id uuid NOT NULL DEFAULT gen_random_uuid(),user_id uuid NOT NULL,target_type public.recommendation_target_type NOT NULL,target_id uuid NOT NULL,score numeric NOT NULL,explanation text,algorithm_version text,generated_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,PRIMARY KEY(id));
CREATE TABLE public.marketplace_transactions(id uuid NOT NULL DEFAULT gen_random_uuid(),listing_id uuid NOT NULL,requester_id uuid NOT NULL,owner_id uuid NOT NULL,transaction_type public.marketplace_listing_type NOT NULL,status public.marketplace_transaction_status NOT NULL DEFAULT 'requested',requested_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,completed_at timestamptz,PRIMARY KEY(id));
CREATE TABLE public.collaboration_spaces(id uuid NOT NULL DEFAULT gen_random_uuid(),created_by uuid NOT NULL,title text NOT NULL,description text,topic text,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.course_documents(id uuid NOT NULL DEFAULT gen_random_uuid(),module_id uuid NOT NULL,uploaded_by uuid NOT NULL,file_id uuid NOT NULL,title text NOT NULL,document_type public.document_type NOT NULL DEFAULT 'course',description text,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.collaboration_members(space_id uuid NOT NULL,user_id uuid NOT NULL,member_role text NOT NULL DEFAULT 'member',joined_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(space_id,user_id));
CREATE TABLE public.resource_views(id uuid NOT NULL DEFAULT gen_random_uuid(),user_id uuid NOT NULL,resource_id uuid NOT NULL,viewed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.marketplace_categories(id uuid NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL,PRIMARY KEY(id));
CREATE TABLE public.chat_messages(id uuid NOT NULL DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL,sender public.chat_sender NOT NULL,content text NOT NULL,model_name text,response_time_ms integer,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.marketplace_images(id uuid NOT NULL DEFAULT gen_random_uuid(),listing_id uuid NOT NULL,file_id uuid NOT NULL,sort_order integer NOT NULL DEFAULT 0,PRIMARY KEY(id));
CREATE TABLE public.complaints(id uuid NOT NULL DEFAULT gen_random_uuid(),student_id uuid NOT NULL,assigned_to uuid,module_id uuid,subject text NOT NULL,description text NOT NULL,complaint_type public.complaint_type NOT NULL,status public.complaint_status NOT NULL DEFAULT 'submitted',resolution_note text,submitted_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,PRIMARY KEY(id));
CREATE TABLE public.knowledge_chunks(id uuid NOT NULL DEFAULT gen_random_uuid(),source_type public.knowledge_source_type NOT NULL,source_id uuid NOT NULL,chunk_text text NOT NULL,embedding_reference text,content_hash text,indexed_at timestamptz,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.marketplace_listings(id uuid NOT NULL DEFAULT gen_random_uuid(),seller_id uuid NOT NULL,category_id uuid,title text NOT NULL,description text,listing_type public.marketplace_listing_type NOT NULL,item_condition public.item_condition NOT NULL DEFAULT 'good',price numeric,currency text NOT NULL DEFAULT '''MAD''::bpchar',status public.marketplace_listing_status NOT NULL DEFAULT 'available',published_at timestamptz,closed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.shared_resources(id uuid NOT NULL DEFAULT gen_random_uuid(),space_id uuid NOT NULL,shared_by uuid NOT NULL,library_resource_id uuid,file_id uuid,title text NOT NULL,description text,shared_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.resource_categories(id uuid NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL,PRIMARY KEY(id));
CREATE TABLE public.message_sources(message_id uuid NOT NULL,knowledge_chunk_id uuid NOT NULL,relevance_score numeric,PRIMARY KEY(message_id,knowledge_chunk_id));
CREATE TABLE public.announcements(id uuid NOT NULL DEFAULT gen_random_uuid(),author_id uuid NOT NULL,module_id uuid,title text NOT NULL,body text NOT NULL,announcement_type text NOT NULL DEFAULT 'general',published_at timestamptz,expires_at timestamptz,status text NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.library_resource_programs(resource_id uuid NOT NULL,program_id uuid NOT NULL,PRIMARY KEY(resource_id,program_id));
CREATE TABLE public.campus_locations(id uuid NOT NULL DEFAULT gen_random_uuid(),classroom_id uuid,name text NOT NULL,location_type public.campus_location_type NOT NULL,building text,floor_label text,description text,latitude numeric,longitude numeric,map_x numeric,map_y numeric,PRIMARY KEY(id));
CREATE TABLE public.files(id uuid NOT NULL DEFAULT gen_random_uuid(),uploaded_by uuid,bucket_id text NOT NULL DEFAULT 'campus-files',object_path text NOT NULL,original_name text NOT NULL,mime_type text NOT NULL,file_size bigint NOT NULL,checksum_sha256 text,visibility text NOT NULL DEFAULT 'authenticated',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.library_resources(id uuid NOT NULL DEFAULT gen_random_uuid(),category_id uuid,uploaded_by uuid,file_id uuid,title text NOT NULL,resource_type public.resource_type NOT NULL,authors text,abstract text,publisher text,publication_year integer,isbn_or_doi text,external_url text,visibility public.resource_visibility NOT NULL DEFAULT 'all_students',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.chat_conversations(id uuid NOT NULL DEFAULT gen_random_uuid(),user_id uuid NOT NULL,title text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.lost_found_items(id uuid NOT NULL DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,item_type public.lost_found_type NOT NULL,title text NOT NULL,description text,location_text text NOT NULL,item_date date,contact_info text,image_file_id uuid,status public.lost_found_status NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.announcement_targets(announcement_id uuid NOT NULL,program_id uuid NOT NULL,PRIMARY KEY(announcement_id,program_id));
CREATE TABLE public.news_posts(id uuid NOT NULL DEFAULT gen_random_uuid(),author_id uuid NOT NULL,title text NOT NULL,content text NOT NULL,cover_file_id uuid,status text NOT NULL DEFAULT 'published',published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.recommendation_feedback(id uuid NOT NULL DEFAULT gen_random_uuid(),recommendation_id uuid NOT NULL,user_id uuid NOT NULL,is_relevant boolean NOT NULL,comment text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
CREATE TABLE public.notifications(id uuid NOT NULL DEFAULT gen_random_uuid(),user_id uuid NOT NULL,title text NOT NULL,body text NOT NULL,notification_type text NOT NULL,related_type text,related_id uuid,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id));
